export const entityEventNames = [
    "issues",
    "issue_comment",
    "pull_request",
    "pull_request_target",
    "pull_request_review",
    "pull_request_review_comment",
];
export const automationEventNames = [
    "workflow_dispatch",
    "repository_dispatch",
    "schedule",
    "workflow_run",
];
export function isSupportedEventName(value) {
    return supportedEventNames.includes(value);
}
export function isAutomaticReviewAction(action) {
    return (action === "opened" ||
        action === "synchronize" ||
        action === "ready_for_review" ||
        action === "reopened");
}
